import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as i,c as e,f as l,q as a,D as o,Q as r,g as p}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const d="/assets/process-cover.BK-_kcmC.jpg",C=JSON.parse('{"title":"Linux 进程管理：ps、top 与 kill 实战指南","description":"","frontmatter":{},"headers":[],"relativePath":"column/Linux/系统管理/进程管理（ps、top、kill）.md","filePath":"column/Linux/系统管理/进程管理（ps、top、kill）.md","lastUpdated":1787968750000}'),h={name:"column/Linux/系统管理/进程管理（ps、top、kill）.md"};function c(g,s,k,u,b,m){const n=i("ArticleMetadata");return l(),e("div",null,[s[0]||(s[0]=a("h1",{id:"linux-进程管理-ps、top-与-kill-实战指南",tabindex:"-1"},[p("Linux 进程管理：ps、top 与 kill 实战指南 "),a("a",{class:"header-anchor",href:"#linux-进程管理-ps、top-与-kill-实战指南","aria-label":'Permalink to "Linux 进程管理：ps、top 与 kill 实战指南"'},"​")],-1)),o(n),s[1]||(s[1]=r('<nav class="table-of-contents"><ul><li><a href="#_1-进程的基础概念">1. 进程的基础概念</a></li><li><a href="#_2-查看静态进程快照-ps-process-status">2. 查看静态进程快照：ps (Process Status)</a><ul><li><a href="#_2-1-常用参数组合">2.1 常用参数组合</a></li><li><a href="#_2-2-生产案例-结合-grep-查找特定服务">2.2 生产案例：结合 grep 查找特定服务</a></li></ul></li><li><a href="#_3-实时动态监控-top-系统任务管理器">3. 实时动态监控：top (系统任务管理器)</a><ul><li><a href="#_3-1-top-界面上半部分-系统整体健康度">3.1 top 界面上半部分（系统整体健康度）</a></li><li><a href="#_3-2-top-快捷交互按键-进入-top-后直接敲击">3.2 top 快捷交互按键（进入 top 后直接敲击）</a></li></ul></li><li><a href="#_4-终止与管理进程-kill-killall-pkill">4. 终止与管理进程：kill / killall / pkill</a><ul><li><a href="#_4-1-核心信号类型">4.1 核心信号类型</a></li><li><a href="#_4-2-实操案例">4.2 实操案例</a></li></ul></li><li><a href="#_5-综合排查实战-cpu-爆满排查步骤">5. 综合排查实战：CPU 爆满排查步骤</a></li><li><a href="#_6-总结">6. 总结</a></li></ul></nav><p><img src="'+d+`" alt="" loading="lazy"></p><p>在 Linux 操作系统中，<strong>进程（Process）</strong> 是正在运行的程序的实例。无论是系统后台运行的服务（如 Nginx、MySQL），还是你执行的命令行脚本，都以进程的形式存在。</p><p>掌握进程管理，是排查服务器卡顿、处理 CPU/内存爆满、以及安全停止异常服务的必备基本功。</p><p>本文将聚焦三大核心命令：<strong>查看静态快照的 <code>ps</code></strong>、<strong>实时监控状态的 <code>top</code></strong>，以及<strong>终止进程的 <code>kill</code></strong>。</p><h2 id="_1-进程的基础概念" tabindex="-1">1. 进程的基础概念 <a class="header-anchor" href="#_1-进程的基础概念" aria-label="Permalink to &quot;1. 进程的基础概念&quot;">​</a></h2><p>在深入命令前，先了解几个核心术语：</p><ul><li><strong>PID（Process ID）</strong>：系统分配给每个进程的唯一数字标识符。</li><li><strong>PPID（Parent Process ID）</strong>：父进程 ID。除了 <code>init</code> / <code>systemd</code>（PID 1）外，所有进程都由另一个进程衍生。</li><li><strong>进程状态</strong>：</li><li><strong>R (Running)</strong>：正在运行或在运行队列中等待。</li><li><strong>S (Sleeping)</strong>：休眠状态，等待某个事件或信号唤醒。</li><li><strong>Z (Zombie)</strong>：<strong>僵尸进程</strong>。子进程已结束，但父进程尚未回收其状态信息，仍占用进程表位置。</li></ul><h2 id="_2-查看静态进程快照-ps-process-status" tabindex="-1">2. 查看静态进程快照：<code>ps</code> (Process Status) <a class="header-anchor" href="#_2-查看静态进程快照-ps-process-status" aria-label="Permalink to &quot;2. 查看静态进程快照：\`ps\` (Process Status)&quot;">​</a></h2><p><code>ps</code> 命令用于捕获<strong>当前时间节点</strong>的进程状态快照。</p><h3 id="_2-1-常用参数组合" tabindex="-1">2.1 常用参数组合 <a class="header-anchor" href="#_2-1-常用参数组合" aria-label="Permalink to &quot;2.1 常用参数组合&quot;">​</a></h3><p>在实际工作中，最常用的组合有两个：</p><h4 id="_1-ps-aux-bsd-风格-最常用" tabindex="-1">1. <code>ps aux</code>（BSD 风格，最常用） <a class="header-anchor" href="#_1-ps-aux-bsd-风格-最常用" aria-label="Permalink to &quot;1. \`ps aux\`（BSD 风格，最常用）&quot;">​</a></h4><ul><li><strong><code>a</code></strong>：显示所有终端下的进程（包括其他用户的进程）。</li><li><strong><code>u</code></strong>：以用户为主的格式显示详细信息（包含 CPU、内存占用等）。</li><li><strong><code>x</code></strong>：显示没有控制终端的后台进程（如系统后台服务）。</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出列解析：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># USER       PID %CPU %MEM    VSZ   RSS TTY      STAT START   TIME COMMAND</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># root         1  0.0  0.1 168128  9640 ?        Ss   Aug27   0:05 /sbin/init</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>**<code>%CPU</code> / <code>%MEM**</code>：占用 CPU 和物理内存的百分比。</li><li><strong><code>RSS</code></strong>：实际使用的物理内存大小（单位 KB）。</li><li><strong><code>STAT</code></strong>：进程状态（<code>S</code> 休眠, <code>s</code> 包含子进程, <code>&lt;</code> 高优先级等）。</li></ul><h4 id="_2-ps-ef-system-v-风格" tabindex="-1">2. <code>ps -ef</code>（System V 风格） <a class="header-anchor" href="#_2-ps-ef-system-v-风格" aria-label="Permalink to &quot;2. \`ps -ef\`（System V 风格）&quot;">​</a></h4><ul><li><strong><code>-e</code></strong>：显示所有进程。</li><li><strong><code>-f</code></strong>：全格式显示（主要用于查看父进程 <strong>PPID</strong> 追溯源头）。</li></ul><h3 id="_2-2-生产案例-结合-grep-查找特定服务" tabindex="-1">2.2 生产案例：结合 <code>grep</code> 查找特定服务 <a class="header-anchor" href="#_2-2-生产案例-结合-grep-查找特定服务" aria-label="Permalink to &quot;2.2 生产案例：结合 \`grep\` 查找特定服务&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看 Node.js 相关的运行进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看端口/进程匹配（排查 MySQL 进程）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mysql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="_3-实时动态监控-top-系统任务管理器" tabindex="-1">3. 实时动态监控：<code>top</code> (系统任务管理器) <a class="header-anchor" href="#_3-实时动态监控-top-系统任务管理器" aria-label="Permalink to &quot;3. 实时动态监控：\`top\` (系统任务管理器)&quot;">​</a></h2><p>如果说 <code>ps</code> 是“拍照”，那 <code>top</code> 就是“录像”。它能<strong>实时动态刷新</strong>系统的 CPU、内存使用率以及各进程的资源消耗。</p><h3 id="_3-1-top-界面上半部分-系统整体健康度" tabindex="-1">3.1 top 界面上半部分（系统整体健康度） <a class="header-anchor" href="#_3-1-top-界面上半部分-系统整体健康度" aria-label="Permalink to &quot;3.1 top 界面上半部分（系统整体健康度）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top - 10:15:30 up 2 days,  4:20,  1 user,  load average: 0.15, 0.20, 0.05</span></span>
<span class="line"><span>Tasks: 120 total,   1 running, 119 sleeping,   0 stopped,   0 zombie</span></span>
<span class="line"><span>%Cpu(s):  2.3 us,  1.0 sy,  0.0 ni, 96.5 id,  0.2 wa,  0.0 hi,  0.0 si</span></span>
<span class="line"><span>MiB Mem :   7950.0 total,   2150.0 free,   3200.0 used,   2600.0 buff/cache</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><p><strong><code>load average</code> (系统负载)</strong>：分别表示 <strong>1 分钟、5 分钟、15 分钟</strong> 内的平均负载。</p></li><li><p><em>判断法则</em>：数值除以 CPU 核心数。若长期大于 1.0/核，说明系统存在排队卡顿。</p></li><li><p><strong><code>%Cpu(s)</code></strong>：</p></li><li><p><strong><code>us</code> (user)</strong>：用户进程消耗 CPU 百分比。</p></li><li><p><strong><code>sy</code> (system)</strong>：内核/系统进程消耗百分比。</p></li><li><p><strong><code>wa</code> (iowait)</strong>：<strong>CPU 等待磁盘 I/O 完成的时间</strong>。该值过高说明磁盘读写瓶颈严重。</p></li><li><p><strong><code>zombie</code></strong>：僵尸进程数量，大于 0 时需关注。</p></li></ul><h3 id="_3-2-top-快捷交互按键-进入-top-后直接敲击" tabindex="-1">3.2 top 快捷交互按键（进入 top 后直接敲击） <a class="header-anchor" href="#_3-2-top-快捷交互按键-进入-top-后直接敲击" aria-label="Permalink to &quot;3.2 top 快捷交互按键（进入 top 后直接敲击）&quot;">​</a></h3><p>在 <code>top</code> 运行界面中，按下以下快捷键可快速分析问题：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>作用</th></tr></thead><tbody><tr><td><strong><code>P</code></strong></td><td>按照 <strong>CPU 占用率</strong> 从高到低排序（默认）</td></tr><tr><td><strong><code>M</code></strong></td><td>按照 <strong>内存占用率 (MEM)</strong> 从高到低排序</td></tr><tr><td><strong><code>N</code></strong></td><td>按照 <strong>PID</strong> 排序</td></tr><tr><td><strong><code>1</code></strong></td><td>展开/折叠显示<strong>每个 CPU 核心</strong>的独立占用情况</td></tr><tr><td><strong><code>k</code></strong></td><td>在 top 内部直接结束某个进程（输入 PID 后回车）</td></tr><tr><td><strong><code>q</code></strong></td><td>退出 top 界面</td></tr></tbody></table><blockquote><p>💡 <strong>进阶替代品</strong>：在现代服务器中，通常会使用界面更美观、支持鼠标交互的 <strong><code>htop</code></strong>（需要通过 <code>apt install htop</code> 或 <code>yum install htop</code> 安装）。</p></blockquote><h2 id="_4-终止与管理进程-kill-killall-pkill" tabindex="-1">4. 终止与管理进程：<code>kill</code> / <code>killall</code> / <code>pkill</code> <a class="header-anchor" href="#_4-终止与管理进程-kill-killall-pkill" aria-label="Permalink to &quot;4. 终止与管理进程：\`kill\` / \`killall\` / \`pkill\`&quot;">​</a></h2><p>当进程卡死、死循环或需要优雅重启时，我们使用 <code>kill</code> 相关的工具发送信号（Signal）给进程。</p><h3 id="_4-1-核心信号类型" tabindex="-1">4.1 核心信号类型 <a class="header-anchor" href="#_4-1-核心信号类型" aria-label="Permalink to &quot;4.1 核心信号类型&quot;">​</a></h3><p>使用 <code>kill -l</code> 可以查看所有信号，最核心的三种信号如下：</p><table tabindex="0"><thead><tr><th>信号编号</th><th>信号名称</th><th>作用与含义</th></tr></thead><tbody><tr><td><strong><code>15</code></strong></td><td><strong>SIGTERM</strong> (默认)</td><td><strong>软件终止信号</strong>。通知进程“请平滑关闭”，进程会先保存数据、释放资源再退出。</td></tr><tr><td><strong><code>9</code></strong></td><td><strong>SIGKILL</strong></td><td><strong>无条件强制杀进程</strong>。系统内核直接回收资源，进程无法拦截或拒绝（可能引发数据丢失）。</td></tr><tr><td><strong><code>1</code></strong></td><td><strong>SIGHUP</strong></td><td><strong>挂起/重载信号</strong>。常用于让服务在不重启的情况下<strong>平滑重新加载配置文件</strong>。</td></tr></tbody></table><h3 id="_4-2-实操案例" tabindex="-1">4.2 实操案例 <a class="header-anchor" href="#_4-2-实操案例" aria-label="Permalink to &quot;4.2 实操案例&quot;">​</a></h3><p><strong>实操案例 1：优雅关闭与强制关闭</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 查找应用进程 PID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aux</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 假设找到 PID 为 12345</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 优先尝试优雅关闭 (SIGTERM)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12345</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 如果进程无响应，使用强制杀进程 (SIGKILL)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -9</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 12345</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>实操案例 2：按名称批量杀死进程 (<code>pkill</code> / <code>killall</code>)</strong></p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 杀死名字为 nginx 的所有进程</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">killall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nginx</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 根据进程名模糊匹配并杀死（如杀死所有带有 node 关键字的进程）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 踢出某个指定终端的用户</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pkill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alex</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="_5-综合排查实战-cpu-爆满排查步骤" tabindex="-1">5. 综合排查实战：CPU 爆满排查步骤 <a class="header-anchor" href="#_5-综合排查实战-cpu-爆满排查步骤" aria-label="Permalink to &quot;5. 综合排查实战：CPU 爆满排查步骤&quot;">​</a></h2><p>当收到报警提醒服务器 CPU 使用率达到 100% 时，标准排查流程如下：</p><ol><li><strong>定位问题进程</strong>：输入 <code>top</code>，按下 <code>P</code> 键，找出占用 CPU 最高进程的 <strong>PID</strong>（假设为 <code>8888</code>）。</li><li><strong>确认进程身份</strong>：通过 <code>ps aux | grep 8888</code> 查看该进程对应的完整路径与启动参数。</li><li><strong>深入线程分析（可选）</strong>：如果是 Java/Python 等多线程程序，执行 <code>top -Hp 8888</code> 查看具体是哪个子线程占用过高。</li><li><strong>处理进程</strong>：</li></ol><ul><li>如果是正常业务飙高，检查日志或配合代码分析。</li><li>如果是异常死循环或恶意挖矿程序，使用 <code>kill -9 8888</code> 强制终止。</li></ul><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to &quot;6. 总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具/命令</th><th>核心定位</th><th>典型使用场景</th></tr></thead><tbody><tr><td>**<code>ps aux</code> / <code>ps -ef**</code></td><td><strong>静态快照</strong></td><td>结合 <code>grep</code> 快速精准定位某个具体进程的 PID 和启动路径</td></tr><tr><td><strong><code>top</code></strong></td><td><strong>动态监控</strong></td><td>排查 CPU 爆满、内存泄露、系统高负载（查看 <code>load average</code>）</td></tr><tr><td><strong><code>kill -15</code></strong></td><td><strong>优雅停机</strong></td><td>生产环境首选，给程序留出写日志、保存缓存的时间</td></tr><tr><td><strong><code>kill -9</code></strong></td><td><strong>强行斩杀</strong></td><td>程序卡死或无响应时的最终兜底手段</td></tr></tbody></table>`,45))])}const _